#include <bits/stdc++.h>
using namespace std;

int countDistinctColors(const vector<int>& arr, int start, int end) {
    vector<bool> visitedColors(24, false);
    int distinctCount = 0;
    for (int i = start; i <= end; i++) {
        int color = arr[i];
        if (!visitedColors[color]) {
            visitedColors[color] = true;
            distinctCount++;
        }
    }
    return distinctCount;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int a, b, l, r;
    cin >> a >> b >> l >> r;
    l -= 1;
    r -= 1;
    int totalAB = a + b;
    int repeatCount = 4;
    vector<int> patternArray(totalAB * repeatCount);
    int offsetH = l / totalAB;
