    r -= offsetH * totalAB;
    int segmentCount = (r - l + 1) / totalAB;
    if (segmentCount > 2) r -= (segmentCount - 2) * totalAB;
    int diffVal = max(a - b, 1);
    for (int repIdx = 0; repIdx < repeatCount; repIdx++) {
        for (int k = 0; k < a - diffVal; k++)
            patternArray[totalAB * repIdx + k] = k;
        for (int k = 0; k < diffVal; k++)
            patternArray[totalAB * repIdx + a - diffVal + k] = (repIdx % 2 == 0) ? a - diffVal + k : a + k;
    }
    int minColors = a + a;
    for (int shiftAIdx = 1; shiftAIdx <= diffVal; shiftAIdx++) {
        for (int k = 0; k < b; k++)
            patternArray[a + k] = patternArray[a - shiftAIdx];
        for (int shiftBIdx1 = 1; shiftBIdx1 <= diffVal; shiftBIdx1++) {
            for (int k = 0; k < b; k++)
                patternArray[totalAB + a + k] = patternArray[totalAB + a - shiftBIdx1];
