                        patternArray[3 * totalAB + a + k] = patternArray[3 * totalAB + a - shiftBIdx3];
                    minColors = min(minColors, countDistinctColors(patternArray, l, r));
                }
            }
        }
    }
    cout << minColors << "\n";
    return 0;
}

